    union := func(n1, n2 int) bool {
        p1, p2 := find(n1), find(n2)

        if p1 == p2 {
            return false
        }
        if rank[p1] > rank[p2] {
            par[p2] = p1
            rank[p1] += rank[p2]
        } else {
            par[p1] = p2
            rank[p2] += rank[p1]
        }
        return true
    }

    for _, edge := range edges {
        n1, n2 := edge[0], edge[1]
        if !union(n1, n2) {
